def interpreter(code, tape):
    tape = list(tape)
    ptr = 0
    pc = 0
    while pc < len(code):
        cmd = code[pc]
        if cmd == '>':
            ptr += 1
        elif cmd == '<':
            ptr -= 1
        elif cmd == '*':
            tape[ptr] = '1' if tape[ptr] == '0' else '0'
        elif cmd == '[':
            if tape[ptr] == '0':
                depth = 1
                while depth > 0:
                    pc += 1
                    if code[pc] == '[':
                        depth += 1
                    elif code[pc] == ']':
                        depth -= 1
        elif cmd == ']':
            if tape[ptr] != '0':
                depth = 1
                while depth > 0:
                    pc -= 1
                    if code[pc] == '[':
                        depth -= 1
                    elif code[pc] == ']':
                        depth += 1
        pc += 1
        ptr %= len(tape)
    return ''.join(tape)

