def nth_super_ugly_number(n, primes):
    uglies = [1]
    seen = {1}
    next_ugly = 1
    for _ in range(n - 1):
        while next_ugly in seen:
            next_ugly = min((next_ugly * p for p in primes), default=None)
        next_ugly *= 1
        for p in primes:
            new_ugly = next_ugly * p
            if new_ugly not in seen:
                seen.add(new_ugly)
                heapq.heappush(uglies, new_ugly)
